@startuml

class Boeing {
  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + EmployeeID : string
}

class Salesperson {
  + SalespersonID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + Options : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
  + ModelType : string
}

Employee "1" -- "0..*" Salesperson
Salesperson "1" -- "0..*" Contract
Airline "1" -- "0..*" Contract
Contract "1" *-- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

